//! A modelled remote: the payment gateway a job charges is a `Remote` the
//! run owns, with its own seeded `Rng`, so its variance (it is sometimes
//! busy, and it dedupes by idempotency key as a real one does) replays with
//! the seed.
//!
//! Run it in your app: copy this file to `tests/sim.rs` and run
//! `charpente test --sim`. In a charpente checkout: `cargo run -p charpente
//! --example modelled_remote`, with any flag after `--` (`-- --master-seed 0x…`).
//!
//! A drawn 48 to 96 orders are placed under the run's faults, the process is
//! power-cycled, and a fault-free tail lets every charge settle. The claim:
//! the gateway applies no order twice, and an order is paid exactly when its
//! job is Done. Delete the idempotency key from `charge`'s call and
//! the gateway sees a fresh key on every retry, so a lost reply charges twice
//! and the run goes red (GUIDE §8, "The outside world: remote models").
//!
//! `charpente_sim::drive` runs the four steps (GUIDE §8, "A fault-free tail
//! for an end-of-run check"):
//! 1. Boot: the app boots through fault fallout, booting again as a
//!    supervisor would; a first boot that never gets past it leaves the
//!    faulted phase empty, and the run goes on.
//! 2. Faulted phase: the orders are placed under the run's faults, with the
//!    sim's outbound handle, since the app declares a host. A fault ends the
//!    phase, and the replies already sent stand.
//! 3. Fault-free tail: a power cycle, the disk, clock and outbound faults
//!    switched off, a clock refusal waited out, and the app booted again and
//!    run to a horizon past every backoff and deadline. The gateway's own
//!    switch is the workload's: it calms the gateway before the tail.
//! 4. Re-send: the tail places again every order the phase left unanswered,
//!    as a client that never saw its answer would.

use std::collections::BTreeMap;
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::Duration;

use charpente::core::io::{OutboundCall, OutboundReply};
use charpente::core::job::{JobRow, JobStatus};
use charpente::core::table::Codec as _;
use charpente::http::{ApiError, App, AppConfig, Method, Request};
use charpente::kernel::JobError;
use charpente::outbound::{Call, Host, IdempotencyKey, Reply};
use charpente::{Id, Schema, Tx, View, job, jobs, route, routes, table};
use charpente_sim::Sim;
use charpente_sim::checks::{
    calls_have_durable_jobs, durable_corruption_fired, keys_are_per_job,
    outbound_settles_by_horizon,
};
use charpente_sim::drive::Drive;
use charpente_sim::outbound::Remote;
use charpente_sim::rng::Rng;

#[table(global)]
struct Order {
    id: Id<Order>,
    paid: bool,
}

#[job(
    global,
    outbound = "pay.example",
    retry(max = 8, backoff = "500ms"),
    timeout = "2s"
)]
struct Charge {
    order: Id<Order>,
}

impl Charge {
    fn call(&self, _tx: &Tx, key: &IdempotencyKey) -> Result<Option<Call>, JobError> {
        Ok(Some(
            Call::post("/charge")
                .header("idempotency-key", key.as_str())
                .form(&[("order", self.order.raw().to_string())]),
        ))
    }

    fn settle(self, tx: &mut Tx, reply: Reply) -> Result<(), JobError> {
        match reply.status() {
            200 => {
                tx.put(&Order {
                    id: self.order,
                    paid: true,
                });
                Ok(())
            }
            s => Err(JobError::app(format!("pay.example answered {s}"))),
        }
    }
}

/// Puts the order and enqueues its charge in one transaction. An order that
/// is already stored is answered as placed and changes nothing: a client
/// re-sends an order it never saw answered, as the drive's tail does, and an
/// order whose first send landed before its answer was lost must not get a
/// second charge under a fresh key. The request is the order's id alone, so
/// a repeat is always the same request; a route whose request carries data
/// refuses other data under a stored id (GUIDE §8, "A route the tail re-sends
/// must be safe to receive twice"). Delete the three lines of the guard and
/// `-- --master-seed 0xf931428f591be3a4` fails 22 of 242 tested runs
/// (`--seed 0x74e75093966cb76d`, shrunk to `orders=48`).
#[route(POST "/orders/:id", public)]
fn place_order(tx: &mut Tx, id: Id<Order>) -> Result<Id<Order>, ApiError> {
    if tx.get(id)?.is_some() {
        return Ok(id);
    }
    tx.put(&Order { id, paid: false });
    tx.enqueue(Charge { order: id });
    Ok(id)
}

fn build_app(sim: &Sim) -> std::io::Result<App> {
    Ok(App::open(
        Box::new(sim.disk()),
        Schema::new().table::<Order>(),
        Box::new(sim.entropy()),
        AppConfig::default(),
    )?
    .mount(routes![place_order])
    .mount_jobs(jobs![Charge])
    .outbound(Host::new("pay.example")))
}

// The remote's side is not exactly-once. `settle` commits at most once, so
// the app's state stays exactly-once, but a remote that ignores the key may
// apply a retry twice; this gateway dedupes, so the claim below holds. The
// minted key belongs to one job: an effect the app may enqueue again (a
// redrive, a re-issued step) is a new job with a new key, so its call must
// send an id of the effect itself, as `order=<id>` does here. Platform
// support for a re-issued job that keeps its effect's key is planned for
// 0.5.0 (PLAN).

/// The gateway. It answers 503 one request in five until the workload calms
/// it, and a request it accepts is applied once per idempotency key: a repeat
/// of a key gets the first charge back and moves no money.
struct Gateway {
    calm: Arc<AtomicBool>,
    by_key: BTreeMap<String, String>,
    /// The order of every charge applied, in the order they were applied.
    charged: Vec<u64>,
}

impl Remote for Gateway {
    fn handle(&mut self, call: &OutboundCall, rng: &mut Rng) -> OutboundReply {
        let reply = |status, body: &str| OutboundReply {
            status,
            headers: Vec::new(),
            body: body.as_bytes().to_vec(),
        };
        if !self.calm.load(Ordering::Relaxed) && rng.chance(0.2) {
            return reply(503, "busy");
        }
        let key = call
            .headers
            .iter()
            .find(|(name, _)| name.eq_ignore_ascii_case("idempotency-key"))
            .map(|(_, value)| value.clone());
        if let Some(charge) = key.as_ref().and_then(|k| self.by_key.get(k)) {
            return reply(200, charge);
        }
        let order = std::str::from_utf8(&call.body)
            .ok()
            .and_then(|body| body.strip_prefix("order="))
            .and_then(|n| n.parse::<u64>().ok())
            .expect("the job posts order=<id>");
        let charge = format!("ch_{}", self.charged.len());
        self.charged.push(order);
        if let Some(key) = key {
            self.by_key.insert(key, charge.clone());
        }
        reply(200, &charge)
    }
}

// `fault:outbound_lost_reply` is what makes "once" a claim: a lost reply is
// the only way a charge is sent twice. The gateway's own 503s retry without
// it, so a batch that never lost a reply would pass a double charge. The
// axis is on in a quarter of runs, at a rate under 3% a call, so the order
// count is what makes it fire: with 48 to 96 orders a reply is lost in about
// one run in seventeen, and a 256-run batch misses it about once in five
// million batches. With 4 to 8 orders it missed 15 batches in 1000.
charpente_sim::sim_tests! {
    each_order_is_charged_once require ["fault:outbound_lost_reply", "outbound:checked"],
}

fn each_order_is_charged_once(sim: &mut Sim) -> Result<(), String> {
    let orders = sim.input().between("orders", 48, 96);
    let calm = Arc::new(AtomicBool::new(false));
    sim.remote(
        "pay.example",
        Gateway {
            calm: Arc::clone(&calm),
            by_key: BTreeMap::new(),
            charged: Vec::new(),
        },
    );

    // The faulted phase: post the orders 20 ms apart and run past the first
    // retries; the tail's power cycle may find a charge in flight.
    let requests: Vec<(Duration, Request)> = (1..=orders)
        .map(|id| {
            (
                Duration::from_millis(id * 20),
                Request::new(Method::Post, format!("/orders/{id}")),
            )
        })
        .collect();
    let drive = Drive::new(sim, build_app);
    let phase = drive.faulted_phase(&requests, Duration::from_secs(3))?;
    // The fault-free tail: eight attempts back off 0.5 s doubling to 32 s,
    // each with a 2 s deadline, well inside the 600 s horizon.
    calm.store(true, Ordering::Relaxed);
    let Some(recovered) = drive.recover(&phase, Duration::from_secs(600))? else {
        return Ok(()); // given up by name
    };

    let snap = recovered
        .kernel
        .app()
        .db()
        .snapshot()
        .map_err(|e| e.to_string())?;
    keys_are_per_job(&snap)?;
    outbound_settles_by_horizon(&snap)?;
    if let Err(e) = calls_have_durable_jobs(sim, &snap) {
        // Media corruption can cut an enqueue whose call already reached the
        // gateway; excused only where it fired, and as a skipped run.
        if durable_corruption_fired(sim) {
            sim.give_up("durable corruption cut an enqueue after its call", e);
            return Ok(());
        }
        return Err(e);
    }

    let jobs = snap.scan::<JobRow>().map_err(|e| e.to_string())?;
    let mut charges = Vec::new();
    for row in jobs.iter().filter(|row| row.outbound_key.is_some()) {
        charges.push((
            row,
            Charge::decode(&mut &row.payload[..]).map_err(|e| e.to_string())?,
        ));
    }
    let charged = sim.with_remote("pay.example", |g: &Gateway| g.charged.clone());
    let mut per_order: BTreeMap<u64, u32> = BTreeMap::new();
    for order in &charged {
        *per_order.entry(*order).or_insert(0) += 1;
    }
    if let Some((order, n)) = per_order.iter().find(|(_, n)| **n > 1) {
        // Two Charge jobs for one order mean the route placed it twice, each
        // job with its own key; one job applied twice is a re-call with no key.
        let placed = charges
            .iter()
            .filter(|(_, job)| job.order.raw() == *order)
            .count();
        if placed > 1 {
            return Err(format!(
                "double charge: pay.example applied order {order} {n} times, and the store holds \
                 {placed} Charge jobs for it — the order was placed twice (a re-sent POST \
                 /orders/{order} whose first send landed), so each call carried its own job's \
                 key: make place_order answer an order that is already stored"
            ));
        }
        return Err(format!(
            "double charge: pay.example applied order {order} {n} times — a re-call carried no \
             idempotency key the gateway could dedupe on"
        ));
    }
    let mut judged = 0;
    for (row, job) in &charges {
        let order = snap
            .get::<Order>(job.order)
            .map_err(|e| e.to_string())?
            .ok_or_else(|| format!("job {} charges an order that is not stored", row.id.raw()))?;
        if (row.status == JobStatus::Done) != order.paid {
            return Err(format!(
                "job {} is {:?} but order {} reads paid = {} — settle's write and the Done mark \
                 commit as one record",
                row.id.raw(),
                row.status,
                job.order.raw(),
                order.paid
            ));
        }
        let n = per_order.get(&job.order.raw()).copied().unwrap_or(0);
        if row.status == JobStatus::Done && n != 1 {
            return Err(format!(
                "job {} is Done, but pay.example applied order {} {n} times",
                row.id.raw(),
                job.order.raw()
            ));
        }
        judged += 1;
    }
    if judged == 0 {
        sim.give_up(
            "no POST /orders became durable, so no charge was judged",
            "",
        );
        return Ok(());
    }
    sim.cover("outbound:checked");
    Ok(())
}

//! Drawn inputs: a property that holds for ANY bids, checked on bids the
//! simulator draws, and shrunk to the fewest and simplest when it fails.
//!
//! Run it in your app: copy this file to `tests/sim.rs` and run
//! `charpente test --sim`. In a charpente checkout: `cargo run -p charpente
//! --example drawn_inputs`, with any flag after `--` (`-- --master-seed 0x…`).
//!
//! The app keeps the highest bid per lab, and the check posts 2 to 6 drawn
//! bids, in a drawn order, through the production kernel loop. Hand-written
//! amounts that happen to ascend cannot tell "keep the highest" from "keep
//! the latest"; amounts the run draws can, and a failure comes back as the
//! two bids that break it (GUIDE §8, "Drawing inputs"). Delete
//! `place_bid`'s `Some(best) if best.amount >= amount` arm, so the latest bid
//! always wins, and run it again to watch that.
//!
//! Faults end the faulted phase, not the run, and the recovered state is
//! judged against the same bounds: "every acked bid is held" is exactly the
//! durability claim. Giving up at the first fault instead would skip nearly
//! half the runs and test nothing about them. `charpente_sim::drive` runs the
//! four steps (GUIDE §8, "A fault-free tail for an end-of-run check"):
//! 1. Boot: the app boots through fault fallout, booting again as a
//!    supervisor would; a first boot that never gets past it leaves the
//!    faulted phase empty, and the run goes on.
//! 2. Faulted phase: the bids are posted under the run's faults. A fault ends
//!    the phase, and the replies already sent stand.
//! 3. Fault-free tail: a power cycle, the faults switched off, a clock
//!    refusal waited out, and the app booted again.
//! 4. Re-send: the tail sends again every bid the phase left unanswered, as a
//!    client that never saw its ack would, and reports those answers apart.
//!    This check merges them into its judgement itself.
//!
//! The same file is the shape of a `tests/sim.rs`: `sim_tests!` supplies
//! `main`, which parses `--runs`, `--seed` and the rest, runs the batch and
//! exits with its code.

use std::time::Duration;

use charpente::http::{ApiError, App, AppConfig, Method, Request};
use charpente::{Id, Schema, Tx, View, Wire, route, routes, table};
use charpente_sim::Sim;
use charpente_sim::checks::durable_corruption_fired;
use charpente_sim::drive::Drive;
use serde::{Deserialize, Serialize};

#[table(global)]
struct Best {
    id: Id<Best>,
    amount: u64,
    memo: String,
}

#[derive(Wire, Serialize, Deserialize)]
struct Bid {
    lab: Id<Best>,
    /// `u32`, not `u64`: a bare `u64` cannot cross the wire (GUIDE §5).
    amount: u32,
    memo: String,
}

/// Keeps the highest bid per lab, and the memo that came with it.
#[route(POST "/bids", public)]
fn place_bid(tx: &mut Tx, bid: Bid) -> Result<Id<Best>, ApiError> {
    let id = bid.lab;
    let amount = u64::from(bid.amount);
    match tx.get(id)? {
        Some(best) if best.amount >= amount => {}
        _ => tx.put(&Best {
            id,
            amount,
            memo: bid.memo,
        }),
    }
    Ok(id)
}

charpente_sim::sim_tests! {
    the_highest_acked_bid_stands require ["restart", "sometimes:judged_a_lab"],
}

/// How the app builds itself on the run's disk. The drive calls it once per
/// boot.
fn build_app(sim: &Sim) -> std::io::Result<App> {
    Ok(App::open(
        Box::new(sim.disk()),
        Schema::new().table::<Best>(),
        Box::new(sim.entropy()),
        AppConfig::default(),
    )?
    .mount(routes![place_bid]))
}

/// The highest bid per lab stands, whatever order the bids arrive in, and
/// through a power cycle. Three claims, none of which names a number:
/// - a lab with an acked bid holds at least the highest amount acked for it;
/// - no lab holds more than the highest amount anyone sent it;
/// - the memo a lab holds is one that was sent for that lab.
///
/// A bid with no ack may or may not have landed before the fault, and the
/// tail re-sends it, so the claims bound the row rather than pin it. Merging
/// the re-sent answers in weakens the durability claim only for a lab whose
/// re-sent bid outranks a lost ack, since that lab holds the higher amount
/// either way; without the merge the check judges only the bids the faulted
/// phase acked.
fn the_highest_acked_bid_stands(sim: &mut Sim) -> Result<(), String> {
    // Every draw is named and recorded: a failure lists them on its
    // `inputs:` line, shrunk, and `--inputs` replays them.
    let input = sim.input();
    let count = input.between("bids", 2, 6);
    let mut labs: Vec<u64> = (0..count).map(|_| *input.pick("lab", &[1, 2])).collect();
    input.shuffle("order", &mut labs);
    let bids: Vec<Bid> = labs
        .into_iter()
        .map(|lab| Bid {
            lab: Id::from_raw(lab),
            amount: input.between("amount", 1, 1000) as u32,
            memo: input.text("memo", &["rush", "bulk", "gift", "late"], 1, 2),
        })
        .collect();

    // One bid a millisecond, counted from the phase's start.
    let requests: Vec<(Duration, Request)> = bids
        .iter()
        .enumerate()
        .map(|(at, b)| {
            (
                Duration::from_millis(at as u64),
                Request::new(Method::Post, "/bids").json(b),
            )
        })
        .collect();

    let drive = Drive::new(sim, build_app);
    let phase = drive.faulted_phase(&requests, Duration::from_millis(100))?;
    let Some(recovered) = drive.recover(&phase, Duration::from_millis(100))? else {
        return Ok(()); // given up by name, on a durable refusal
    };
    // The tail acks what it re-sent, so every run judges a merge that saw its
    // bids, in a drawn order, across a power cycle. A re-sent bid's answer is
    // the tail's; any other bid's is the phase's, `None` for none.
    let statuses: Vec<Option<u16>> = (0..bids.len())
        .map(|i| recovered.status(i).or(phase.status(i)))
        .collect();
    let snap = recovered
        .kernel
        .app()
        .db()
        .snapshot()
        .map_err(|e| e.to_string())?;
    let mut judged = false;
    for lab in [1u64, 2] {
        let sent = || {
            bids.iter()
                .zip(&statuses)
                .filter(|(b, _)| b.lab.raw() == lab)
        };
        let acked_max = sent()
            .filter(|(_, s)| **s == Some(200))
            .map(|(b, _)| b.amount)
            .max();
        let sent_max = sent().map(|(b, _)| b.amount).max();
        let held = snap
            .get::<Best>(Id::from_raw(lab))
            .map_err(|e| e.to_string())?;
        let Some(sent_max) = sent_max else {
            continue; // no bid was sent to this lab
        };
        let Some(held) = held else {
            let Some(acked_max) = acked_max else {
                continue; // nothing acked, nothing landed: nothing it must hold
            };
            // Acked-but-lost is excused ONLY where the harness injected
            // durable corruption into this run (GUIDE §8, "Giving up").
            if durable_corruption_fired(sim) {
                sim.give_up("durable corruption fired, so the acked row is excused", "");
                return Ok(());
            }
            return Err(format!(
                "lab {lab} has a bid of {acked_max} acked but no Best row"
            ));
        };
        if let Some(acked_max) = acked_max
            && held.amount < u64::from(acked_max)
        {
            if durable_corruption_fired(sim) {
                sim.give_up("durable corruption fired, so the acked row is excused", "");
                return Ok(());
            }
            return Err(format!(
                "lab {lab} holds {} but a bid of {acked_max} was acked: the highest bid must stand, whatever order bids arrive in",
                held.amount
            ));
        }
        if held.amount > u64::from(sent_max) {
            return Err(format!(
                "lab {lab} holds {} but the highest bid sent was {sent_max}",
                held.amount
            ));
        }
        if !sent().any(|(b, _)| b.memo == held.memo) {
            return Err(format!(
                "lab {lab} holds the memo {:?}, which no bid for it carried",
                held.memo
            ));
        }
        judged = true;
    }
    if judged {
        sim.cover("sometimes:judged_a_lab");
    } else {
        sim.give_up("no bid landed, so there was nothing to judge", "");
    }
    Ok(())
}
//! A restart under faults: what a client was told is durable stays durable
//! across a power cycle, and the check judges the recovery in a fault-free
//! tail.
//!
//! Run it in your app: copy this file to `tests/sim.rs` and run
//! `charpente test --sim`. In a charpente checkout: `cargo run -p charpente
//! --example restart_under_faults`, with any flag after `--` (`-- --master-seed 0x…`).
//!
//! `charpente_sim::drive` runs the four steps (GUIDE §8, "A fault-free tail
//! for an end-of-run check"):
//! 1. Boot: the app boots through fault fallout, booting again as a
//!    supervisor would; a first boot that never gets past it leaves the
//!    faulted phase empty, and the run goes on.
//! 2. Faulted phase: the entries are posted through the production kernel
//!    loop while the simulated disk and clock misbehave. A fault ends the
//!    phase, not the run, and the replies already sent stand.
//! 3. Fault-free tail: `sim.restart()` power-cycles the disk, the faults are
//!    switched off, a clock refusal is waited out, and the app boots again.
//! 4. Re-send: the tail sends again every entry the phase left unanswered.
//!
//! The check then reads back every entry the faulted phase acked. Delete the
//! `tx.put` in `add_entry` and run again to watch it go red with a seed.

use std::time::Duration;

use charpente::http::{ApiError, App, AppConfig, Method, Request};
use charpente::{Id, Schema, Tx, View, Wire, route, routes, table};
use charpente_sim::Sim;
use charpente_sim::checks::durable_corruption_fired;
use charpente_sim::drive::Drive;
use serde::{Deserialize, Serialize};

#[table(global)]
struct Entry {
    id: Id<Entry>,
    text: String,
}

#[derive(Wire, Serialize, Deserialize)]
struct NewEntry {
    text: String,
}

#[route(POST "/entries/:id", public)]
fn add_entry(tx: &mut Tx, id: Id<Entry>, body: NewEntry) -> Result<Id<Entry>, ApiError> {
    tx.put(&Entry {
        id,
        text: body.text,
    });
    Ok(id)
}

// The claim is about a restart, so the batch must contain restarts: a run
// that never power-cycled would pass a lost write.
charpente_sim::sim_tests! {
    an_acked_entry_survives_a_restart require ["restart"],
}

/// How the app builds itself on the run's disk. The drive calls it once per
/// boot.
fn build_app(sim: &Sim) -> std::io::Result<App> {
    Ok(App::open(
        Box::new(sim.disk()),
        Schema::new().table::<Entry>(),
        Box::new(sim.entropy()),
        AppConfig::default(),
    )?
    .mount(routes![add_entry]))
}

/// An acked entry is durable: after a crash every acked row is still there,
/// with the text it was acked with.
fn an_acked_entry_survives_a_restart(sim: &mut Sim) -> Result<(), String> {
    let input = sim.input();
    let count = input.between("entries", 1, 4);
    let entries: Vec<(u64, String)> = (1..=count)
        .map(|id| (id, input.text("text", &["alpha", "bravo", "charlie"], 1, 3)))
        .collect();
    // One entry a millisecond, counted from the phase's start.
    let requests: Vec<(Duration, Request)> = entries
        .iter()
        .enumerate()
        .map(|(at, (id, text))| {
            (
                Duration::from_millis(at as u64),
                Request::new(Method::Post, format!("/entries/{id}"))
                    .json(&NewEntry { text: text.clone() }),
            )
        })
        .collect();

    let drive = Drive::new(sim, build_app);
    let phase = drive.faulted_phase(&requests, Duration::from_secs(2))?;
    let Some(recovered) = drive.recover(&phase, Duration::from_secs(1))? else {
        return Ok(()); // given up by name, on a durable refusal
    };
    // An entry with no 200 in the faulted phase may or may not have landed,
    // so there is no claim about it; its re-send is the tail's.
    let acked: Vec<&(u64, String)> = entries
        .iter()
        .enumerate()
        .filter(|(i, _)| phase.status(*i) == Some(200))
        .map(|(_, entry)| entry)
        .collect();
    if acked.is_empty() {
        sim.give_up("no POST was acked, so durability has nothing to prove", "");
        return Ok(());
    }
    let snap = recovered
        .kernel
        .app()
        .db()
        .snapshot()
        .map_err(|e| e.to_string())?;
    for (id, text) in acked {
        match snap.get::<Entry>(Id::from_raw(*id)) {
            Ok(Some(row)) if row.text == *text => {}
            Ok(Some(row)) => {
                return Err(format!(
                    "acked entry {id} came back as {:?}, not the {text:?} it was acked with",
                    row.text
                ));
            }
            // Acked-but-lost is excused ONLY where the harness injected
            // durable corruption into this run (GUIDE §8, "Giving up").
            Ok(None) if durable_corruption_fired(sim) => {
                sim.give_up("durable corruption fired, so the acked row is excused", "");
                return Ok(());
            }
            Ok(None) => return Err(format!("acked entry {id} lost across a crash")),
            Err(e) => return Err(e.to_string()),
        }
    }
    Ok(())
}

