/// A patron is known only by id: the subject of their credential is
/// `patron:<id>`. Not a table: the platform `ApiKey` row is their record.
pub struct Patron;

@[table(global)]
pub struct Branch {
    pub id: Id<Branch>,
    pub name: String,
}

@[table(global)]
pub struct Title {
    pub id: Id<Title>,
    pub name: String,
}

/// How many copies of one title one branch holds, and where they are: set
/// aside for a ready hold, or out with a patron who picked one up. The rest
/// are free on the shelf. `slot` is `"<branch>:<title>"`.
@[table(global)]
pub struct Stock {
    pub id: Id<Stock>,
    @[index]
    pub slot: String,
    pub branch: Id<Branch>,
    pub title: Id<Title>,
    pub copies: u32,
    pub set_aside: u32,
    pub on_loan: u32,
}

impl Stock {
    /// Copies on the shelf that no hold has and no patron has out.
    pub fn free(&self) -> u32 {
        self.copies.saturating_sub(self.set_aside + self.on_loan)
    }
}

