    pub id: Id<Hold>,
    @[index]
    pub patron: Id<Patron>,
    pub title: Id<Title>,
    pub branch: Id<Branch>,
    @[index]
    pub slot: String,
    @[index]
    pub state: HoldState,
    pub placed_seq: u64,
    pub ready_seq: Option<u64>,
    pub ready_hour: Option<u64>,
    pub ended_seq: Option<u64>,
    pub ended_hour: Option<u64>,
    pub notified: bool,
}

