    pub branch: Id<Branch>,
    pub title: Id<Title>,
}

/// The one-time operator bootstrap: present once the first operator key was
/// minted.
@[table(global)]
pub struct OperatorSeat {
    pub id: Id<OperatorSeat>,
}
